#!/usr/bin/env python
"""Strip duplicated enum CHECK constraints from an autogenerated migration.

Why this exists
---------------
Our enums are ``sa.Enum(..., native_enum=False, create_constraint=True)``:
the value set is enforced with a ``CHECK`` constraint instead of a PostgreSQL
``ENUM`` type (adding a member later is then a plain constraint swap).

Alembic's autogenerate renders that constraint **three times** — once named
after the enum, once through the naming convention, and once more when
``op.create_table`` instantiates the column type. The result is
``ERROR: constraint ... already exists``.

The type already adds the constraint (with the convention name
``ck_<table>_<enum>``), so the two explicit renderings are simply removed.

Usage (wired into ``make migration``)::

    alembic revision --autogenerate -m "change"
    python scripts/fix_migration.py alembic/versions/<file>.py
"""

from __future__ import annotations

import re
import sys
from pathlib import Path

ENUM_DECL = re.compile(r"name='(?P<name>[a-z0-9_]+)',\s*native_enum=False")
CHECK_LINE = re.compile(r"^\s*sa\.CheckConstraint\(")
NAME_ARG = re.compile(r"name=(?P<name>op\.f\('(?P<conv>[^']+)'\)|'(?P<plain>[^']+)')")


def enum_names(text: str) -> set[str]:
    return {m.group("name") for m in ENUM_DECL.finditer(text)}


def is_enum_check(line: str, enums: set[str]) -> bool:
    match = NAME_ARG.search(line)
    if not match:
        return False
    plain = match.group("plain")
    converted = match.group("conv")
    if plain and plain in enums:
        return True
    # convention name: ck_<table>_<enum type name>
    return bool(converted) and any(converted.endswith(f"_{enum}") for enum in enums)


def process(path: Path) -> int:
    text = path.read_text(encoding="utf-8")
    enums = enum_names(text)
    if not enums:
        return 0

    out: list[str] = []
    removed = 0
    for line in text.splitlines(keepends=True):
        if CHECK_LINE.match(line) and is_enum_check(line, enums):
            removed += 1
            continue
        out.append(line)

    if removed:
        path.write_text("".join(out), encoding="utf-8")
    return removed


def main(argv: list[str]) -> int:
    if len(argv) < 2:
        print(__doc__)
        return 2
    total = 0
    for raw in argv[1:]:
        path = Path(raw)
        if not path.exists():
            print(f"! {path} not found")
            return 1
        removed = process(path)
        total += removed
        print(f"  {path.name}: removed {removed} duplicated enum CHECK constraint(s)")
    print(f"done ({total} removed)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))
